def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_vehicle_position()
    x = pos[0]
    vel = sandbox.get_vehicle_velocity()
    vx = vel[0]

    # Apply force to counteract damping in mud zone
    if 5.5 <= x <= 7.5:
        sandbox.apply_force(agent_body, (1000, 0))
    # Apply impulse in impulse zone to boost speed
    elif 8.0 <= x <= 9.0:
        sandbox.apply_force(agent_body, (500, 0))
    # Apply force in decel zone to maintain speed
    elif 9.5 <= x <= 11.0:
        sandbox.apply_force(agent_body, (1000, 0))
