        if vx < 2.8:
            sandbox.apply_force(agent_body, (1000, 0))
    # Check checkpoint at x=11.0
    elif x >= 11.0:
        if vx < 1.1 or vx > 2.7:
            sandbox.apply_force(agent_body, (-100, 0))

